//! The CI generator and this crate's parser have to agree, and nothing in
//! either side's own tests can prove that: \`scripts/release-manifest.mjs\` is
//! JavaScript producing JSON, \`manifest.rs\` is Rust consuming it. A renamed
//! field would leave both suites green and the updater silently unable to read
//! any real release.
//!
//! So this test parses the manifest the real generator wrote. The fixture is
//! regenerated by running the generator over fake artifacts with the filenames
//! the actual CI produced for v0.1.9 -- if the contract changes, this fails
//! here rather than in the field.

use box_updates::UpdateManifest;

const FIXTURE: &str = include_str!("fixtures/latest.json");

#[test]
fn the_generator_output_parses_through_the_rust_reader() {
    let manifest = UpdateManifest::parse(FIXTURE).expect("the generator's output must parse");
    assert_eq!(manifest.version, "0.1.9");
    assert_eq!(manifest.minimum_version.as_deref(), Some("0.1.9"));
    assert_eq!(manifest.schema, 1);
}

#[test]
fn every_published_platform_is_readable_and_carries_a_usable_digest() {
    let manifest = UpdateManifest::parse(FIXTURE).expect("parse");
    // Linux ships two installers for one machine; the rest ship one. Both
    // are read out of the same shape, which is why the shape is an array.
    assert_eq!(manifest.assets_for("linux-x64").unwrap().len(), 2);
    assert_eq!(manifest.assets_for("win-x64").unwrap().len(), 1);
    assert_eq!(manifest.assets_for("macos-arm64").unwrap().len(), 1);
    for (platform, assets) in &manifest.platforms {
        for asset in assets {
            assert_eq!(
                asset.sha256.len(),
                64,
                "{platform}: the digest must be a bare SHA-256 hex string"
            );
            assert!(
                asset.url.starts_with("https://github.com/Nexus-Aethra/DSHBox/releases/download/"),
                "{platform}: {} is not a release asset URL",
                asset.url
            );
            assert!(asset.size > 0, "{platform}: an asset with no size is not one");
            assert!(asset.is_automatic() == matches!(asset.installer.as_str(), "msi" | "dmg"),
                "{platform}: {} should only be automatic where it needs no root",
                asset.installer);
        }
    }
}

#[test]
fn the_manifest_this_release_publishes_allows_an_in_place_install() {
    // minimumVersion equals the released version, so a 0.1.9 build may update
    // itself in place with this release and an older one may not.
    let manifest = UpdateManifest::parse(FIXTURE).expect("parse");
    assert!(manifest.installable_from("0.1.9"));
    assert!(!manifest.installable_from("0.1.8"));
}
